\label{scissor}
Let $0\rightarrow L\rightarrow M\rightarrow N\rightarrow 0$ be a short exact sequence of representations of $Q$. Then the following conditions are equivalent:
\begin{enumerate}
    \item $\mu(L)\leq \mu(M)$,
    \item $\mu(L)\leq\mu(N)$,
    \item $\mu(M)\leq\mu(N)$.
\end{enumerate}

\label{scss_lem}
Let $M$ be a representation of $Q$. There is a unique subrepresentation $N$ such that 
\begin{enumerate}
    \item $\mu(N)$ is maximal among subrepresentations of $M$, and 
    \item if $\mu(N')=\mu(N)$, then $N'\subseteq N$.
\end{enumerate}

\label{HN}
Let $M$ be a representation of $Q$. There is a unique filtration $0=M_0\subsetneq M_1\subsetneq \cdots\subsetneq M_{r-1}\subsetneq M_r = M$ such that 
\begin{enumerate}
\item $\mu(M_i/M_{i-1})>\mu(M_{i+1}/M_{i})$ for $i=1,\ldots, r-1$,
\item the representation $M_i/M_{i-1}$ is $\mu$-semistable for $i=1,\ldots,r$.
\end{enumerate}

Let $M$ be a representation of dimension $\mathbf{d}$ and let $N\subset M$ be any subrepresentation. We then have 
\begin{equation*}
\begin{split}
    \mu(N)=\frac{\Theta(N)}{\kappa(N)}\leq \mu(M)=\frac{\Theta(\mathbf{d})}{\kappa(\mathbf{d})}\Leftrightarrow \kappa(\mathbf{d})\Theta(N)-\Theta(\mathbf{d})\kappa(N)=\theta_{\mathbf{d}}(N)\leq 0
    \end{split}
\end{equation*}
The first statement follows.

For the second statement, simply note that $$\mu_{\mathbf{d}}(N) = \kappa(\mathbf{d})\cdot \mu(N)-\Theta(\mathbf{d}).$$ Hence $\mu_{\mathbf{d}}$ is a positive scalar multiple of $\mu$, followed by a translation.

