Let $U$ be the minimal $c$-shrunk subspace of $\mathcal{A}_{W,\theta}$, and let $V=\sum_{\varphi}A(\varphi)(U)$. For each $i,r$ (resp. $j,q$), let $\pi_{i,r}:\bigoplus_{i}W_{x_i}^{\theta_{+}(x_i)}\rightarrow W_{x_i}$ (resp. $\pi_{j,q}: \bigoplus_{j}W_{y_j}^{\theta_{-}(y_j)}\rightarrow W_{y_j}$) be the projection onto the $(i,r)$-th (resp. $(j,q)$-th) component.
The following properties then hold:
\begin{enumerate}
    \item $U=\bigoplus_{i}(W'_{x_i})^{\theta_{+}(x_i)}$, where $W'_{x_i}=\pi_{i,r}(U)\subseteq W_{x_i}$ for any $r\in I^{+}_{i}$.
    \item $V=\bigoplus_{j}(W'_{y_j})^{\theta_{-}(y_j)}$, where $W'_{y_j}=\pi_{j,q}(V)=\sum_{i,p\in\mathcal{P}_{i,j}}W(p)(W'_{x_i})\subseteq W_{y_j}$ for any $q\in I_{j}^{-}$.
\end{enumerate}

Let $u\in U$ and let $p$ be a path from $x_{i'}$ to $x_{i}$ in the $(r',r)$-th component of $\mathrm{End}(P_1)\simeq \bigoplus_{i,i'}(P_{x_{i'}})_{x_i}^{\theta_{+}(x_{i'})\theta_{+}(x_{i})}.$ The pre-composition $u\circ p$ is then $W(p)(\pi_{i',r'}(u))$ placed in the $r$-th component of $W(x_{i})^{\theta_{+}(x_i)}$. Since $U$ is a right $\text{End}(P_{1})$-module, and the same path $p$ can be placed in any $(r',r)$-th component of $\mathrm{End}(P_1)$, the image $W(p)(\pi_{i'r'}(u))$ when placed in the $r$-th component of $W(x_{i})^{\sigma_{+}(x_i)}$, is still in $U$ for any $r'\in I^{+}
